H.background();
const v = H.plot2d({ xMin: -8, xMax: 8, yMin: -8, yMax: 8 });
v.grid(); v.axes();
const m = P.m, b = P.b, c = P.c;
// Line 1 (already solved for y):  y = m*x + b
v.fn(x => m * x + b, { color: H.colors.accent, width: 3 });
// Line 2 is the horizontal "what we substitute INTO":  x = c  (a vertical line),
// but to keep it a real system we use the second equation  y = -x + c  here.
v.fn(x => -x + c, { color: H.colors.accent2, width: 3 });
H.text("Substitution: put y = m·x + b into the 2nd equation", 24, 30, { color: H.colors.ink, size: 16, weight: 700 });
if (Math.abs(m + 1) > 1e-6) {
  // solve m*x + b = -x + c  ->  x = (c - b)/(m + 1)
  const xi = (c - b) / (m + 1), yi = m * xi + b;
  // animated vertical "drop" showing the substituted x-value being found
  const sweep = xi * (0.5 + 0.5 * Math.sin(t * 1.2));
  v.line(sweep, 0, sweep, m * sweep + b, { color: H.colors.violet, width: 2, dash: [4, 4] });
  v.dot(sweep, 0, { r: 5, fill: H.colors.violet });
  H.circle(v.X(xi), v.Y(yi), 6 + 1.5 * Math.sin(t * 3), { fill: H.colors.warn });
  v.line(xi, 0, xi, yi, { color: H.colors.good, width: 2, dash: [3, 3] });
  H.text("solve for x: x = (c − b)/(m + 1) = " + xi.toFixed(2) + ",  y = " + yi.toFixed(2), 24, 52, { color: H.colors.good, size: 13 });
} else {
  H.text("m = −1: lines parallel — substitution gives no x", 24, 52, { color: H.colors.warn, size: 13 });
}
H.legend([{ label: "y = m·x + b", color: H.colors.accent }, { label: "y = −x + c", color: H.colors.accent2 }], H.W - 160, 28);
